292→	/**
293→	 * 시스템 사전과 그외 사전들을 처음부터 다시 읽어들여서 머징한뒤,
294→	 * 현재사용중인 context 에 있는 사전에 적용한다.
295→	 * */
296→	public static void reloadDictionary() {
297→		if (baseFile == null || configFile == null) {
298→			logger.error("DICTIONARY NOT LOADED!");
299→			return;
300→		}
301→		ProductNameDictionary newCommonDictionary = loadDictionary(baseFile, ResourceResolver.readYmlConfig(configFile));
302→		ProductNameDictionary commonDictionary = contextStore.getAs(PRODUCT_NAME_DICTIONARY, ProductNameDictionary.class);
303→		// 1. commonDictionary에 systemdictinary셋팅.
304→		commonDictionary.reset(newCommonDictionary);
305→		// 2. dictionaryMap 에 셋팅.
306→		Map<String, SourceDictionary<?>> dictionaryMap = commonDictionary.getDictionaryMap();
307→
308→		for (Entry<String, SourceDictionary<?>> entry : dictionaryMap.entrySet()) {
309→			String dictionaryId = entry.getKey();
310→			SourceDictionary<?> dictionary = entry.getValue();
311→			// dictionary 객체 자체는 유지하고, 내부 실데이터(map,set등)만 업데이트해준다.
312→			// 상속시 instanceof로는 정확한 클래스가 판별이 불가능하므로 isAssignableFrom 로 판별한다.
313→			if (dictionary.getClass().isAssignableFrom(SetDictionary.class)) {
314→				SetDictionary setDictionary = (SetDictionary) dictionary;
315→				SetDictionary newDictionary = newCommonDictionary.getDictionary(dictionaryId, SetDictionary.class);
316→				setDictionary.setSet(newDictionary.set());
317→			} else if (dictionary.getClass().isAssignableFrom(MapDictionary.class)) {
318→				MapDictionary mapDictionary = (MapDictionary) dictionary;
319→				MapDictionary newDictionary = newCommonDictionary.getDictionary(dictionaryId, MapDictionary.class);
320→				mapDictionary.setMap(newDictionary.map());
321→			} else if (dictionary.getClass().isAssignableFrom(SynonymDictionary.class)) {
322→				SynonymDictionary synonymDictionary = (SynonymDictionary) dictionary;
323→				SynonymDictionary newDictionary = newCommonDictionary.getDictionary(dictionaryId, SynonymDictionary.class);
324→				synonymDictionary.setMap(newDictionary.map());
325→				synonymDictionary.setWordSet(newDictionary.getWordSet());
326→			} else if (dictionary.getClass().isAssignableFrom(SpaceDictionary.class)) {
327→				SpaceDictionary spaceDictionary = (SpaceDictionary) dictionary;
328→				SpaceDictionary newDictionary = newCommonDictionary.getDictionary(dictionaryId, SpaceDictionary.class);
329→				spaceDictionary.setMap(newDictionary.map());
330→				spaceDictionary.setWordSet(newDictionary.getWordSet());
331→			} else if (dictionary.getClass().isAssignableFrom(CustomDictionary.class)) {
332→				CustomDictionary customDictionary = (CustomDictionary) dictionary;
333→				CustomDictionary newDictionary = newCommonDictionary.getDictionary(dictionaryId, CustomDictionary.class);
334→				customDictionary.setMap(newDictionary.map());
335→				customDictionary.setWordSet(newDictionary.getWordSet());
336→			} else if (dictionary.getClass().isAssignableFrom(CompoundDictionary.class)) {
337→				CompoundDictionary compoundDictionary = (CompoundDictionary) dictionary;
338→				CompoundDictionary newDictionary = newCommonDictionary.getDictionary(dictionaryId, CompoundDictionary.class);
339→				compoundDictionary.setMap(newDictionary.map());
340→			}
341→			logger.info("Dictionary [{}] is reloaded!", dictionaryId);
342→		}
343→		newCommonDictionary = null;
344→	}
