350→	public static void compileDictionary(NodeClient client, final DictionaryRepository repo,
351→										 String filter, final boolean exportFile) {
352→		if (baseFile == null || configFile == null) {
353→			logger.error("DICTIONARY NOT LOADED!");
354→		}
355→
356→		Set<String> filters = new HashSet<>();
357→		if(filter != null){
358→			String[] split = filter.trim().split(",");
359→			for(String item : split){
360→				filters.add(item.toLowerCase());
361→			}
362→		}
363→		logger.info("Compile Dict types: {}", filters);
364→
365→		JSONObject dictProp = ResourceResolver.readYmlConfig(configFile);
366→		JSONArray dictList = dictProp.optJSONArray(ATTR_DICTIONARY_LIST);
367→		String basePath = dictProp.optString(ATTR_DICTIONARY_BASE_PATH);
368→
369→		for (int inx = 0; inx < dictList.length(); inx++) {
