409→	public static Map<String, Object> compileDictionaryOne(final DictionaryRepository repo,
410→														   JSONArray dictList, String dictionaryId) {
411→
412→		Map<String, Object> result = new HashMap<>();
413→
414→		// dictList 설정을 스캔하면서 dictionaryId를 찾는다.
415→		for (int inx = 0; inx < dictList.length(); inx++) {
416→			JSONObject row = dictList.optJSONObject(inx);
417→			String dictId = row.optString(ATTR_DICTIONARY_NAME);
418→			if (!dictionaryId.equals(dictId)) {
419→				continue;
420→			}
421→			Type type = getType(row);
422→			String tokenType = getTokenType(row);
423→			String label = getLabel(row);
424→			int seq = getSeq(row);
425→			boolean ignoreCase = row.optBoolean(ATTR_DICTIONARY_IGNORECASE, true);
426→
427→			Iterator<CharSequence[]> source = repo.getSource(dictionaryId);
428→
429→			//사전 타입으로 객체생성.
430→			SourceDictionary<?> sourceDictionary = null;
431→			if (type == Type.SET) {
432→				sourceDictionary = new SetDictionary(ignoreCase);
433→			} else if (type == Type.MAP) {
434→				sourceDictionary = new MapDictionary(ignoreCase);
435→			} else if (type == Type.SYNONYM || type == Type.SYNONYM_2WAY) {
436→				sourceDictionary = new SynonymDictionary(ignoreCase);
437→			} else if (type == Type.SPACE) {
438→				sourceDictionary = new SpaceDictionary(ignoreCase);
439→			} else if (type == Type.CUSTOM) {
440→				sourceDictionary = new CustomDictionary(ignoreCase);
441→			} else if (type == Type.INVERT_MAP) {
442→				sourceDictionary = new InvertMapDictionary(ignoreCase);
443→			} else if (type == Type.COMPOUND) {
444→				sourceDictionary = new CompoundDictionary(ignoreCase);
445→			}
446→			//사전객체에 데이터 입력.
447→			if (sourceDictionary != null) {
448→				int cnt = 0;
449→				for (; source.hasNext(); cnt++) {
450→					CharSequence[] data = source.next();
451→					String id = "";
452→					String keyword = "";
453→					String value = "";
454→					String line = "";
455→					if (data[0] != null) {
456→						id = String.valueOf(data[0]).trim();
457→					}
458→					if (data[1] != null) {
459→						keyword = String.valueOf(data[1]).trim();
460→					}
461→					if (data[2] != null) {
462→						value = String.valueOf(data[2]).trim();
463→					}
464→					if (type == Type.SYNONYM || type == Type.SYNONYM_2WAY) {
465→						if (keyword.length() > 0) {
466→							line = keyword + "\t" + value;
467→						} else {
468→							line = value;
469→						}
470→					} else if (type == Type.CUSTOM) {
471→						if (id.length() > 0) {
472→							line = keyword + "\t" + id;
473→						} else {
474→							line = keyword;
475→						}
476→					} else {
477→						if (value.length() > 0) {
478→							line = keyword + "\t" + value;
479→						} else {
480→							line = keyword;
481→						}
482→					}
483→					sourceDictionary.addSourceLineEntry(line);
484→				}
485→				result.put("cnt", cnt);
486→				logger.info("DICTIONARY LOADED! [{}] / {} / {} / {}", cnt, dictionaryId, type, tokenType);
487→			}
488→			result.put("dict", sourceDictionary);
489→			result.put("type", dictId);
490→			result.put("id", dictId);
491→			return result;
492→		}
493→		return null;
494→	}
