package com.danawa.search.analysis.product.action;

import com.danawa.search.analysis.dict.ProductNameDictionary;
import com.danawa.search.analysis.product.AnalysisProductNamePlugin;
import com.danawa.util.ContextStore;

import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.elasticsearch.action.ActionType;
import org.elasticsearch.action.FailedNodeException;
import org.elasticsearch.action.support.ActionFilters;
import org.elasticsearch.action.support.nodes.TransportNodesAction;
import org.elasticsearch.cluster.node.DiscoveryNode;
import org.elasticsearch.cluster.service.ClusterService;
import org.elasticsearch.common.io.stream.StreamInput;
import org.elasticsearch.injection.guice.Inject;
import org.elasticsearch.tasks.Task;
import org.elasticsearch.threadpool.ThreadPool;
import org.elasticsearch.transport.TransportService;

import java.io.IOException;
import java.util.List;

/**
 * ES 9.1.2 TransportNodesAction 기반 클러스터 전체 사전 리로드 액션
 *
 * <p>각 노드에서 병렬로 실행되며, 결과를 코디네이터 노드에서 집계합니다.</p>
 *
 * <p>사용 예시:</p>
 * <pre>
 * POST /_analysis-product-name/reload-dict
 * {
 *   "type": "SYNONYM",
 *   "force": true
 * }
 * </pre>
 */
public class TransportReloadDictAction extends TransportNodesAction<
        ReloadDictNodesRequest,
        ReloadDictNodesResponse,
        ReloadDictNodeRequest,
        ReloadDictNodeResponse,
        Void> {  // ES 9.1.2: ActionContext 추가 (Void 사용)

    /** Action 이름 - 클러스터 관리 네임스페이스 사용 */
    public static final String ACTION_NAME = "cluster:admin/analysis/dict/reload";

    /** ActionType 정의 - ES 9.1.2에서 Action 등록에 사용 */
    public static final ActionType<ReloadDictNodesResponse> TYPE = new ActionType<>(ACTION_NAME);

    private static final Logger logger = LogManager.getLogger(TransportReloadDictAction.class);

    /** 플러그인 컨텍스트 저장소 - 사전 인스턴스 관리 */
    private static final ContextStore contextStore = ContextStore.getStore(AnalysisProductNamePlugin.class);

    /**
     * ES 9.1.2 생성자 - Guice 의존성 주입
     *
     * @param threadPool      스레드 풀 (MANAGEMENT executor 사용)
     * @param clusterService  클러스터 서비스
     * @param transportService 트랜스포트 서비스
     * @param actionFilters   액션 필터
     */
    @Inject
    public TransportReloadDictAction(
            ThreadPool threadPool,
            ClusterService clusterService,
            TransportService transportService,
            ActionFilters actionFilters) {
        super(
            ACTION_NAME,
            clusterService,
            transportService,
            actionFilters,
            // ES 9.1.2: Writeable.Reader만 전달 (노드 요청 역직렬화용)
            ReloadDictNodeRequest::new,
            // ES 9.1.2: MANAGEMENT executor (사전 로딩은 I/O 바운드 작업)
            threadPool.executor(ThreadPool.Names.MANAGEMENT)
        );
    }

    /**
     * 클러스터 전체 응답 생성
     */
    @Override
    protected ReloadDictNodesResponse newResponse(
            ReloadDictNodesRequest request,
            List<ReloadDictNodeResponse> responses,
            List<FailedNodeException> failures) {
        return new ReloadDictNodesResponse(clusterService.getClusterName(), responses, failures);
    }

    /**
     * 개별 노드 요청 생성 - 최소한의 페이로드만 전달
     */
    @Override
    protected ReloadDictNodeRequest newNodeRequest(ReloadDictNodesRequest request) {
        return new ReloadDictNodeRequest(request.getDictionaryType());
    }

    /**
     * 노드 응답 역직렬화
     */
    @Override
    protected ReloadDictNodeResponse newNodeResponse(StreamInput in, DiscoveryNode node) throws IOException {
        return new ReloadDictNodeResponse(in);
    }

    /**
     * 각 노드에서 실행되는 핵심 로직
     */
    @Override
    protected ReloadDictNodeResponse nodeOperation(ReloadDictNodeRequest request, Task task) {
        DiscoveryNode localNode = clusterService.localNode();
        long startTime = System.currentTimeMillis();

        try {
            logger.info("[{}] Dictionary reload started, type={}",
                localNode.getName(), request.getDictionaryType());

            // 사전 인스턴스 확인
            if (!contextStore.containsKey(ProductNameDictionary.PRODUCT_NAME_DICTIONARY)) {
                logger.warn("[{}] Dictionary not initialized", localNode.getName());
                return new ReloadDictNodeResponse(
                    localNode, false, "Dictionary not initialized", 0, 0
                );
            }

            ProductNameDictionary dictionary = contextStore.getAs(
                ProductNameDictionary.PRODUCT_NAME_DICTIONARY,
                ProductNameDictionary.class
            );

            if (dictionary == null) {
                return new ReloadDictNodeResponse(
                    localNode, false, "Dictionary instance is null", 0, 0
                );
            }

            // 사전 리로드 실행
            ProductNameDictionary.reloadDictionary();

            long elapsed = System.currentTimeMillis() - startTime;
            int size = getDictionarySize(dictionary);

            logger.info("[{}] Dictionary reload completed in {}ms, size={}",
                localNode.getName(), elapsed, size);

            return new ReloadDictNodeResponse(
                localNode, true, "Reload successful", elapsed, size
            );

        } catch (Exception e) {
            long elapsed = System.currentTimeMillis() - startTime;
            logger.error("[{}] Dictionary reload failed: {}", localNode.getName(), e.getMessage(), e);

            return new ReloadDictNodeResponse(
                localNode, false, e.getMessage(), elapsed, 0
            );
        }
    }

    /**
     * 사전 크기 조회 (안전하게 처리)
     */
    private int getDictionarySize(ProductNameDictionary dictionary) {
        try {
            if (dictionary.getDictionaryMap() != null) {
                return dictionary.getDictionaryMap().size();
            }
        } catch (Exception e) {
            logger.debug("Failed to get dictionary size", e);
        }
        return 0;
    }
}

