import com.danawa.search.analysis.product.action.RestReloadDictAction;
import com.danawa.search.analysis.product.action.TransportReloadDictAction;

import static java.util.Collections.singletonMap;

import java.util.HashMap;

public class AnalysisProductNamePlugin extends Plugin implements AnalysisPlugin, ActionPlugin {

	private static final Logger logger = LogManager.getLogger(AnalysisProductNamePlugin.class);

	public AnalysisProductNamePlugin() {
		logger.trace("init");
	}

	/**
	 * 필터 등록. 
	 * ES 에서 product_name 이름으로 상품명 필터를 생성하여 사용할수 있도록 등록.
	 */
	@Override public Map<String, AnalysisProvider<TokenFilterFactory>> getTokenFilters() {
		Map<String, AnalysisProvider<TokenFilterFactory>> extra = new HashMap<>();
		extra.put("product_name", ProductNameAnalysisFilterFactory::new);
		return extra;
	}

	/**
	 * 토크나이저 등록.
	 * ES 에서 product_name 이름으로 토크나이저를 생성하여 사용할수 있도록 토크나이저 등록.
	 */
	@Override public Map<String, AnalysisProvider<TokenizerFactory>> getTokenizers() {
		return singletonMap("product_name", ProductNameTokenizerFactory::new);
	}

	/**
	 * 분석기 등록. 
	 * ES 에서 product_name 이름으로 상품명분석기를 생성하여 사용할수 있도록 분석기를 등록>
	 */
	@Override public Map<String, AnalysisProvider<AnalyzerProvider<? extends Analyzer>>> getAnalyzers() {
		return singletonMap("product_name", ProductNameAnalyzerProvider::new);
	}

	/**
	 * Transport Action 등록
	 * ES 9.1.2: 클러스터 내부 노드 간 통신을 위한 Transport Action 등록
	 */
	@Override
	public List<ActionHandler> getActions() {
		return List.of(
			new ActionHandler(TransportReloadDictAction.TYPE, TransportReloadDictAction.class)
		);
	}

	/**
	 * REST 액션 핸들러 등록
	 * ES 에 상호작용이 가능한 REST 액션 핸들러를 등록한다.
	 */
	@Override
	public List<RestHandler> getRestHandlers(Settings settings, NamedWriteableRegistry namedWriteableRegistry,
		RestController controller, ClusterSettings clusterSettings, IndexScopedSettings indexScopedSettings,
		SettingsFilter filter, IndexNameExpressionResolver resolver, Supplier<DiscoveryNodes> nodes,
		Predicate<NodeFeature> clusterSupportsFeature) {
		List<RestHandler> handlers = new ArrayList<>();
		handlers.add(new ProductNameAnalysisAction());
		handlers.add(new RestReloadDictAction());  // 클러스터 전파 reload API
		return handlers;
	}
}

