/**
 * ES 사전 색인 조회용 클래스
 * 사전 컴파일 등에 사용한다.
 */
public static class DictionarySource extends DictionaryRepository implements Iterator<CharSequence[]> {
	private Client client;
	private RemoteNodeClient remoteClient;
	private String index;
	private Iterator<Map<String, Object>> iterator;
	private List<Map<String, Object>> remoteResults;
	private int remoteIndex;

	public DictionarySource(Client client, String index) {
		this.client = client;
		this.index = index;
	}

	public DictionarySource(RemoteNodeClient remoteClient, String index) {
		this.remoteClient = remoteClient;
		this.index = index;
	}

	@Override public Iterator<CharSequence[]> getSource(String type) {
		try {
			QueryBuilder query = QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, type.toUpperCase());
			logger.trace("QUERY:{}", query);

			if (remoteClient != null) {
				// RemoteNodeClient를 사용한 원격 검색
				remoteResults = new ArrayList<>();
				remoteIndex = 0;
				org.elasticsearch.action.search.SearchRequest searchRequest = new org.elasticsearch.action.search.SearchRequest();
				org.elasticsearch.search.builder.SearchSourceBuilder sourceBuilder = new org.elasticsearch.search.builder.SearchSourceBuilder();
				sourceBuilder.query(query).size(10000);
				searchRequest.indices(index).source(sourceBuilder);

				JSONObject response = remoteClient.search(searchRequest);
				if (response != null && response.has("hits")) {
					JSONObject hits = response.getJSONObject("hits");
					org.json.JSONArray hitsArray = hits.getJSONArray("hits");
					for (int i = 0; i < hitsArray.length(); i++) {
						JSONObject hit = hitsArray.getJSONObject(i);
						JSONObject source = hit.getJSONObject("_source");
						Map<String, Object> map = new HashMap<>();
						for (String key : source.keySet()) {
							map.put(key, source.get(key));
						}
						remoteResults.add(map);
					}
				}
			} else {
				// 로컬 Client를 사용한 검색
				iterator = SearchUtil.search(client, index, query, null, null, 0, -1, true, null);
			}
		} catch (Exception e) {
			logger.error("", e);
		}
		return this;
	}

	@Override public void restore(String type, boolean ignoreCase, Set<CharSequence> wordSet) {
		if (client == null) {
			logger.warn("restore() is not supported for RemoteNodeClient");
			return;
		}
		Map<String, Object> source = null;
		BulkRequestBuilder builder = null;
		try {
			builder = client.prepareBulk();
			int inx = 0;
			for (CharSequence data : wordSet) {
				String[] words = String.valueOf(data).split(TAB);
				source = new HashMap<>();
				source.put(ES_DICT_FIELD_TYPE, type.toUpperCase());
				if (words.length == 1) {
					source.put(ES_DICT_FIELD_KEYWORD, words[0]);
				} else if (words.length == 2) {
					if (words[0].length() > 0) {
						source.put(ES_DICT_FIELD_KEYWORD, words[0]);
					}
					source.put(ES_DICT_FIELD_VALUE, words[1]);
				} else {
					source.put(ES_DICT_FIELD_KEYWORD, words[0]);
					source.put(ES_DICT_FIELD_VALUE, words[1]);
					source.put(ES_DICT_FIELD_ID, words[2]);
				}
				builder.add(client.prepareIndex(String.valueOf(index)).setSource(source));
				if (inx > 0 && inx % 1000 == 0) {
					builder.execute().actionGet();
					builder = client.prepareBulk();
				}
				inx++;
			}
			if (inx > 0) {
				builder.execute().actionGet();
			}
		} catch (Exception e) {
			logger.error("", e);
		}
	}

	@Override public boolean hasNext() {
		if (remoteClient != null) {
			return remoteResults != null && remoteIndex < remoteResults.size();
		}
		return iterator != null && iterator.hasNext();
	}

	@Override public CharSequence[] next() {
		Map<String, Object> data;
		if (remoteClient != null) {
			data = remoteResults.get(remoteIndex++);
		} else {
			data = iterator.next();
		}
		CharSequence id = CharVector.valueOf(data.get(ES_DICT_FIELD_ID));
		CharSequence keyword = CharVector.valueOf(data.get(ES_DICT_FIELD_KEYWORD));
		CharSequence value = CharVector.valueOf(data.get(ES_DICT_FIELD_VALUE));
